function resolveLessonContent(skillId, lessonId) {
  const skill = LESSON_CONTENT[skillId];
  if (!skill) return null;
  const lesson = skill[Number(lessonId)];
  if (!lesson) return null;
  return lesson;
}

function buildLessonContext(skillId, lessonId) {
  const lesson = resolveLessonContent(skillId, lessonId);
  if (!lesson) return '';
  return [
    `عنوان الدرس: ${lesson.title}`,
    lesson.description ? `هدف/وصف الدرس: ${lesson.description}` : '',
    'المحتوى التعليمي المعتمد:',
    lesson.content,
    lesson.example ? `مثال تطبيقي من الدرس:\n${lesson.example}` : ''
  ].filter(Boolean).join('\n\n');
}

module.exports = { LESSON_CONTENT, resolveLessonContent, buildLessonContext };
